[TFMDescription("Converts values to decimal")]
class TFMLogicContextToDecimal extends TFMLogicContextTools
{
}

Method.Source:
public static TFMLogicContextToDecimal Construct()
{
    return new TFMLogicContextToDecimal();
}

protected void new()
{
    super();
    inputTypes.add(TFMLogicContextTypes::String);
    //inputTypes.add(TFMLogicContextTypes::Date);
    inputTypes.add(TFMLogicContextTypes::Boolean);
    inputTypes.add(TFMLogicContextTypes::Integer);
    outputType = TFMLogicContextTypes::Decimal;
    noOfInput = 1;
    categories.add("@TFM:TypeConversion");
}

public Object process()
{
    Object ret;


    return ret;
}

public anytype evaluate(TFMLogicContext _context)
{
    anytype         ret;
    SetEnumerator   sEnum;
    TFMCondition    condition;
    str             value;

    if (children == null)
    {
        return 0.0;
    }

    sEnum = children.getEnumerator();

    while (sEnum.moveNext())
    {
        condition = sEnum.current();
        ret = condition.evaluate(_context);
    }

    // Numeric values and numeric strings
    real result = any2Real(ret);

    // If conversion produced a non-zero number, use it
    if (result != 0)
    {
        return result;
    }

    return 0.0;
}
